import { APP_LANG } from '../../../core/i18n/models/app-lang.const';
import type { AppLang } from '../../../core/i18n/models/app-lang.type';
import type { FolderEmojiNames } from '../models/folder-emoji-names.type';

/**
 * The emoji names of each language, a lazy chunk each (a few kB, generated by
 * `scripts/build-folder-emoji.mjs` from emojibase-data): loaded on the first open of the picker.
 */
const loaders: Readonly<Record<AppLang, () => Promise<FolderEmojiNames>>> = {
  [APP_LANG.En]: async () => (await import('../emoji-names/en.json')).default,
  [APP_LANG.Fr]: async () => (await import('../emoji-names/fr.json')).default,
  [APP_LANG.De]: async () => (await import('../emoji-names/de.json')).default,
  [APP_LANG.It]: async () => (await import('../emoji-names/it.json')).default,
  [APP_LANG.Es]: async () => (await import('../emoji-names/es.json')).default,
  [APP_LANG.Pt]: async () => (await import('../emoji-names/pt.json')).default,
};

/** The names for `lang`, English for a language the app does not have. */
export function loadFolderEmojiNames(lang: string): Promise<FolderEmojiNames> {
  return (Object.hasOwn(loaders, lang) ? loaders[lang as AppLang] : loaders[APP_LANG.En])();
}
